from copy import deepcopy
from pathlib import Path
from tempfile import mkdtemp
from ledger import Ledger

backup = Path(mkdtemp(prefix='.ledger-before-', dir='.')) / 'ledger.py'
backup.write_bytes(Path('ledger.py').read_bytes())
print(f'Original source saved for diff: {backup}')

def probe(name, check):
    try:
        check()
    except AssertionError as exc:
        print(f'REPRODUCED {name}: {exc}')
    else:
        print(f'CONTROL PASS {name}')

def valid_transfer():
    ledger = Ledger({'a': 100, 'b': 0})
    assert ledger.transfer('a', 'b', 20, 'one') == dict(source='a', target='b', amount=20, key='one')
    assert ledger.balances == {'a': 80, 'b': 20}

def constructor_copy():
    original = {'a': 100, 'b': 0}
    ledger = Ledger(original)
    ledger.transfer('a', 'b', 20, 'one')
    assert original == {'a': 100, 'b': 0}, f'input changed to {original}'

def invalid_balance():
    try:
        Ledger({'a': True})
    except ValueError:
        return
    assert False, 'boolean balance accepted'

def insufficient_funds():
    ledger = Ledger({'a': 10, 'b': 0})
    try:
        ledger.transfer('a', 'b', 11, 'one')
    except ValueError:
        pass
    assert ledger.balances == {'a': 10, 'b': 0}, f'failed transfer left {ledger.balances}'

def changed_replay():
    ledger = Ledger({'a': 100, 'b': 0})
    ledger.transfer('a', 'b', 20, 'one')
    try:
        ledger.transfer('a', 'b', 30, 'one')
    except ValueError:
        return
    assert False, 'changed amount accepted under an existing key'

def receipt_isolation():
    ledger = Ledger({'a': 100, 'b': 0})
    receipt = ledger.transfer('a', 'b', 20, 'one')
    receipt['amount'] = 999
    assert ledger.history['one']['amount'] == 20, f'history changed to {ledger.history}'

def batch_rollback():
    ledger = Ledger({'a': 100, 'b': 0, 'c': 0})
    before = deepcopy((ledger.balances, ledger.history))
    try:
        ledger.batch([
            dict(source='a', target='b', amount=20, key='one'),
            dict(source='b', target='c', amount=30, key='two'),
        ])
    except ValueError:
        pass
    assert (ledger.balances, ledger.history) == before, f'failed batch left {(ledger.balances, ledger.history)}'

for name, check in [
    ('ordinary transfer', valid_transfer),
    ('constructor input isolation', constructor_copy),
    ('constructor validation', invalid_balance),
    ('failed transfer atomicity', insufficient_funds),
    ('conflicting replay', changed_replay),
    ('returned receipt isolation', receipt_isolation),
    ('batch atomicity', batch_rollback),
]:
    probe(name, check)
PY"

